patch:
diff --git a/percent.js b/percent.js
new file mode 100644
index 0000000..c98cc32
--- /dev/null
+++ b/percent.js
@@ -0,0 +1,5 @@
+function percentOf(value, total) {
+  return (value / total) * 100;
+}
+
+module.exports = { percentOf };
diff --git a/percent.test.js b/percent.test.js
new file mode 100644
index 0000000..4f1d9a5
--- /dev/null
+++ b/percent.test.js
@@ -0,0 +1,9 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { percentOf } = require('./percent');
+
+test('percentOf calculates percentage', () => {
+  assert.strictEqual(percentOf(50, 100), 50);
+  assert.strictEqual(percentOf(10, 200), 5);
+  assert.strictEqual(percentOf(0, 100), 0);
+});
